import { AppState, Apartment, Area, Task } from '../types';
import { INITIAL_APARTMENTS, INITIAL_AREAS, INITIAL_TASKS } from '../constants';

const STORAGE_KEY = 'cleantrack_data_v1';

export const loadState = (): AppState => {
  try {
    const serialized = localStorage.getItem(STORAGE_KEY);
    if (serialized) {
      return JSON.parse(serialized);
    }
  } catch (e) {
    console.error("Failed to load state", e);
  }

  // Return default initial state if nothing in storage
  return {
    apartments: INITIAL_APARTMENTS,
    areas: INITIAL_AREAS,
    tasks: INITIAL_TASKS,
    currentUser: 'Owner'
  };
};

export const saveState = (state: AppState) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch (e) {
    console.error("Failed to save state", e);
  }
};

export const calculateNextDueDate = (frequency: string, completionDate: Date): Date => {
  const nextDate = new Date(completionDate);
  switch (frequency) {
    case 'Daily':
      nextDate.setDate(nextDate.getDate() + 1);
      break;
    case 'Weekly':
      nextDate.setDate(nextDate.getDate() + 7);
      break;
    case 'Bi-Weekly':
      nextDate.setDate(nextDate.getDate() + 14);
      break;
    case 'Monthly':
      nextDate.setMonth(nextDate.getMonth() + 1);
      break;
    case 'Quarterly':
      nextDate.setMonth(nextDate.getMonth() + 3);
      break;
    default:
      nextDate.setDate(nextDate.getDate() + 7);
  }
  return nextDate;
};

import { GoogleGenAI } from "@google/genai";

// NOTE: In a real environment, this should be accessed safely.
// For this demo, we assume the environment variable is set.
const API_KEY = process.env.API_KEY || '';

let ai: GoogleGenAI | null = null;

try {
    if (API_KEY) {
        ai = new GoogleGenAI({ apiKey: API_KEY });
    }
} catch (error) {
    console.error("Failed to initialize Gemini Client", error);
}

export const getCleaningAdvice = async (taskTitle: string, areaName: string): Promise<string> => {
    if (!ai) {
        return "Please configure your API Key to get smart advice.";
    }

    try {
        const model = 'gemini-3-flash-preview';
        const prompt = `
        I need professional cleaning advice for the following task: "${taskTitle}" in the "${areaName}".

        Please provide:
        1. A brief list of recommended tools/products.
        2. A concise step-by-step guide (max 3-4 steps).
        3. A "pro tip" for better results.

        Keep the tone helpful and motivating. Format with simple markdown.
        `;

        const response = await ai.models.generateContent({
            model: model,
            contents: prompt,
        });

        return response.text || "No advice available at the moment.";
    } catch (error) {
        console.error("Gemini API Error:", error);
        return "Sorry, I couldn't fetch the cleaning advice right now. Please try again later.";
    }
};

export const getSmartScheduleSuggestion = async (apartmentType: string, numResidents: number): Promise<string> => {
   if (!ai) return "Gemini not configured.";

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Suggest a cleaning frequency for a ${apartmentType} with ${numResidents} residents. Return just a suggested frequency (Daily, Weekly, Monthly) and a one sentence reason.`,
        });
        return response.text || "Weekly";
    } catch (e) {
        return "Weekly";
    }
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { AppState, Task, Apartment, Area, TaskStatus } from '../types';
import { loadState, saveState, calculateNextDueDate } from '../services/storageService';

interface AppContextType {
  state: AppState;
  completeTask: (taskId: string) => void;
  addTask: (task: Task) => void;
  setCurrentUser: (user: string) => void;
  getTasksByArea: (areaId: string) => Task[];
  getAreasByApartment: (aptId: string) => Area[];
  getApartmentProgress: (aptId: string) => { completed: number, total: number, percentage: number };
  getTotalProgress: () => { completed: number, total: number, percentage: number };
  refreshData: () => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>(loadState());

  useEffect(() => {
    saveState(state);
  }, [state]);

  const refreshData = useCallback(() => {
    setState(loadState());
  }, []);

  const completeTask = (taskId: string) => {
    setState(prev => {
      const newTasks = prev.tasks.map(t => {
        if (t.id === taskId) {
          const now = new Date();
          const nextDue = calculateNextDueDate(t.frequency, now);
          return {
            ...t,
            lastCompletedDate: now.toISOString(),
            nextDueDate: nextDue.toISOString(),
            assignedTo: prev.currentUser
          };
        }
        return t;
      });
      return { ...prev, tasks: newTasks };
    });
  };

  const addTask = (task: Task) => {
    setState(prev => ({
      ...prev,
      tasks: [...prev.tasks, task]
    }));
  };

  const setCurrentUser = (user: string) => {
    setState(prev => ({ ...prev, currentUser: user }));
  };

  const getTasksByArea = (areaId: string) => {
    return state.tasks.filter(t => t.areaId === areaId);
  };

  const getAreasByApartment = (aptId: string) => {
    return state.areas.filter(a => a.apartmentId === aptId);
  };

  const getApartmentProgress = (aptId: string) => {
    const areaIds = state.areas.filter(a => a.apartmentId === aptId).map(a => a.id);
    const tasks = state.tasks.filter(t => areaIds.includes(t.areaId));

    if (tasks.length === 0) return { completed: 0, total: 0, percentage: 100 };

    const now = new Date();
    // A task is "due" if nextDueDate <= now. 
    // We want to calculate "Up to date" status.
    // Let's count tasks that are overdue or due today as "Pending".
    // Tasks due in future are "Completed" (or rather, "Not Due").

    // Actually, for a progress bar, usually we show tasks completed *this cycle*.
    // A simpler metric for "Are we up to date?":
    // Total Tasks = All tasks
    // Pending Tasks = Tasks where nextDueDate < now + 24h
    // Completed/OnTrack = Total - Pending

    const pendingCount = tasks.filter(t => new Date(t.nextDueDate) <= now).length;
    const totalCount = tasks.length;
    const onTrackCount = totalCount - pendingCount;

    return {
      completed: onTrackCount,
      total: totalCount,
      percentage: totalCount === 0 ? 100 : Math.round((onTrackCount / totalCount) * 100)
    };
  };

  const getTotalProgress = () => {
     const tasks = state.tasks;
     if (tasks.length === 0) return { completed: 0, total: 0, percentage: 100 };

     const now = new Date();
     const pendingCount = tasks.filter(t => new Date(t.nextDueDate) <= now).length;
     const totalCount = tasks.length;
     const onTrackCount = totalCount - pendingCount;

     return {
      completed: onTrackCount,
      total: totalCount,
      percentage: totalCount === 0 ? 100 : Math.round((onTrackCount / totalCount) * 100)
    };
  };

  return (
    <AppContext.Provider value={{ 
      state, 
      completeTask, 
      addTask, 
      setCurrentUser, 
      getTasksByArea, 
      getAreasByApartment,
      getApartmentProgress,
      getTotalProgress,
      refreshData
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) {
    throw new Error('useApp must be used within an AppProvider');
  }
  return context;
};

import React, { useState, useEffect } from 'react';
import { getCleaningAdvice } from '../services/geminiService';

interface AIChatModalProps {
  isOpen: boolean;
  onClose: () => void;
  taskTitle: string;
  areaName: string;
}

const AIChatModal: React.FC<AIChatModalProps> = ({ isOpen, onClose, taskTitle, areaName }) => {
  const [advice, setAdvice] = useState<string>('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (isOpen && taskTitle) {
      setLoading(true);
      getCleaningAdvice(taskTitle, areaName)
        .then(text => setAdvice(text))
        .catch(() => setAdvice("Failed to fetch advice."))
        .finally(() => setLoading(false));
    } else {
      setAdvice('');
    }
  }, [isOpen, taskTitle, areaName]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4 animate-fade-in">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[80vh]">
        <div className="bg-gradient-to-r from-primary to-blue-600 p-4 flex justify-between items-center text-white">
          <div className="flex items-center gap-2">
            <i className="fa-solid fa-sparkles text-yellow-300"></i>
            <h3 className="font-bold text-lg">AI Cleaning Assistant</h3>
          </div>
          <button onClick={onClose} className="hover:bg-white/20 rounded-full p-2 transition">
            <i className="fa-solid fa-times"></i>
          </button>
        </div>

        <div className="p-6 overflow-y-auto text-gray-700 leading-relaxed">
          {loading ? (
            <div className="flex flex-col items-center justify-center py-8">
              <i className="fa-solid fa-circle-notch fa-spin text-4xl text-primary mb-4"></i>
              <p className="text-gray-500">Asking Gemini for the best tips...</p>
            </div>
          ) : (
            <div className="prose prose-sm max-w-none">
                <h4 className="text-lg font-semibold text-gray-900 mb-2">
                  How to clean: {taskTitle}
                </h4>
                <div className="whitespace-pre-line text-sm">
                  {advice}
                </div>
            </div>
          )}
        </div>

        <div className="p-4 bg-gray-50 border-t text-xs text-gray-500 text-center">
          Powered by Google Gemini 
        </div>
      </div>
    </div>
  );
};

export default AIChatModal;

import React from 'react';
import { useApp } from '../context/AppContext';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';

interface DashboardProps {
  onSelectApartment: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ onSelectApartment }) => {
  const { state, getApartmentProgress, getTotalProgress } = useApp();
  const totalProgress = getTotalProgress();

  const data = [
    { name: 'On Track', value: totalProgress.completed },
    { name: 'Pending', value: totalProgress.total - totalProgress.completed },
  ];

  const COLORS = ['#10b981', '#fbbf24'];

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Header Section */}
      <div className="bg-white rounded-2xl p-6 shadow-sm border border-gray-100 flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1">
          <h2 className="text-2xl font-bold text-gray-800 mb-2">Welcome back, {state.currentUser}!</h2>
          <p className="text-gray-500">
            You are <span className="font-bold text-primary">{totalProgress.percentage}%</span> up to date with cleaning tasks.
          </p>
        </div>
        <div className="w-48 h-48 relative">
           <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={data}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={80}
                fill="#8884d8"
                paddingAngle={5}
                dataKey="value"
              >
                {data.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
          <div className="absolute inset-0 flex items-center justify-center flex-col pointer-events-none">
             <span className="text-2xl font-bold text-gray-800">{totalProgress.percentage}%</span>
             <span className="text-xs text-gray-400">Complete</span>
          </div>
        </div>
      </div>

      {/* Apartments Grid */}
      <div>
        <h3 className="text-xl font-bold text-gray-800 mb-4 px-2">Your Apartments</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {state.apartments.map(apt => {
            const stats = getApartmentProgress(apt.id);
            return (
              <button
                key={apt.id}
                onClick={() => onSelectApartment(apt.id)}
                className="group bg-white rounded-xl p-6 shadow-sm border border-gray-100 hover:shadow-md transition-all text-left relative overflow-hidden"
              >
                <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition">
                   <i className="fa-solid fa-building text-6xl text-primary"></i>
                </div>

                <h4 className="text-lg font-bold text-gray-800 mb-1">{apt.name}</h4>
                <p className="text-sm text-gray-500 mb-4 flex items-center gap-2">
                  <i className="fa-solid fa-location-dot"></i> {apt.address}
                </p>

                <div className="w-full bg-gray-100 rounded-full h-2.5 mb-2">
                  <div 
                    className="bg-primary h-2.5 rounded-full transition-all duration-500" 
                    style={{ width: `${stats.percentage}%` }}
                  ></div>
                </div>
                <div className="flex justify-between text-xs text-gray-500">
                  <span>{stats.completed} done</span>
                  <span>{stats.total - stats.completed} pending</span>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      <div className="bg-blue-50 border border-blue-100 rounded-lg p-4 text-sm text-blue-700 flex items-start gap-3">
         <i className="fa-solid fa-database mt-1"></i>
         <div>
            <p className="font-semibold">Centralized Database Simulation</p>
            <p className="opacity-80">This demo uses local storage to simulate the centralized database. In a production environment, this would connect to the Google Sheet provided or a cloud database like Firebase to sync between users.</p>
         </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React from 'react';
import { useApp } from '../context/AppContext';
import { Task } from '../types';

interface ApartmentViewProps {
  apartmentId: string;
  onBack: () => void;
  onSelectArea: (areaId: string) => void;
}

const ApartmentView: React.FC<ApartmentViewProps> = ({ apartmentId, onBack, onSelectArea }) => {
  const { state, getAreasByApartment, getTasksByArea } = useApp();
  const apartment = state.apartments.find(a => a.id === apartmentId);
  const areas = getAreasByApartment(apartmentId);

  if (!apartment) return <div>Apartment not found</div>;

  const getAreaStats = (areaId: string) => {
    const tasks = getTasksByArea(areaId);
    const now = new Date();
    const pending = tasks.filter(t => new Date(t.nextDueDate) <= now).length;
    return { total: tasks.length, pending };
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex items-center gap-4">
        <button onClick={onBack} className="p-2 hover:bg-gray-200 rounded-full transition">
          <i className="fa-solid fa-arrow-left text-gray-600"></i>
        </button>
        <h2 className="text-2xl font-bold text-gray-800">{apartment.name}</h2>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
        {areas.map(area => {
          const stats = getAreaStats(area.id);
          const isAllDone = stats.pending === 0;

          return (
            <button
              key={area.id}
              onClick={() => onSelectArea(area.id)}
              className={`
                flex flex-col items-center justify-center p-6 rounded-2xl border transition-all
                ${isAllDone ? 'bg-white border-gray-100' : 'bg-orange-50 border-orange-100'}
                hover:shadow-md hover:-translate-y-1
              `}
            >
              <div className={`
                w-16 h-16 rounded-full flex items-center justify-center mb-4 text-2xl
                ${isAllDone ? 'bg-green-100 text-green-600' : 'bg-orange-100 text-orange-500'}
              `}>
                <i className={`fa-solid ${area.icon}`}></i>
              </div>
              <h3 className="font-semibold text-gray-800 mb-1">{area.name}</h3>
              <span className={`text-xs font-medium px-2 py-1 rounded-full ${isAllDone ? 'bg-green-100 text-green-700' : 'bg-orange-200 text-orange-800'}`}>
                {isAllDone ? 'All Clean' : `${stats.pending} Tasks Due`}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default ApartmentView;

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { Task } from '../types';
import AIChatModal from './AIChatModal';

interface AreaViewProps {
  areaId: string;
  onBack: () => void;
}

const AreaView: React.FC<AreaViewProps> = ({ areaId, onBack }) => {
  const { state, getTasksByArea, completeTask } = useApp();
  const area = state.areas.find(a => a.id === areaId);
  const tasks = getTasksByArea(areaId);

  const [showAI, setShowAI] = useState(false);
  const [selectedTaskForAI, setSelectedTaskForAI] = useState<string>('');

  if (!area) return <div>Area not found</div>;

  const handleComplete = (taskId: string) => {
    completeTask(taskId);
  };

  const handleAskAI = (taskTitle: string) => {
    setSelectedTaskForAI(taskTitle);
    setShowAI(true);
  };

  const sortedTasks = [...tasks].sort((a, b) => {
     // Sort by due date ascending (overdue first)
     return new Date(a.nextDueDate).getTime() - new Date(b.nextDueDate).getTime();
  });

  return (
    <div className="space-y-6 animate-fade-in pb-20">
      <div className="flex items-center justify-between sticky top-0 bg-slate-50/90 backdrop-blur-sm py-4 z-10 border-b border-gray-200">
        <div className="flex items-center gap-3">
            <button onClick={onBack} className="p-2 hover:bg-gray-200 rounded-full transition">
            <i className="fa-solid fa-arrow-left text-gray-600"></i>
            </button>
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-primary/10 rounded-full flex items-center justify-center text-primary">
                    <i className={`fa-solid ${area.icon}`}></i>
                </div>
                <h2 className="text-xl font-bold text-gray-800">{area.name} Tasks</h2>
            </div>
        </div>
      </div>

      <div className="space-y-3">
        {sortedTasks.map(task => {
          const now = new Date();
          const dueDate = new Date(task.nextDueDate);
          const isDue = dueDate <= now;
          const daysOverdue = Math.ceil((now.getTime() - dueDate.getTime()) / (1000 * 3600 * 24));

          return (
            <div 
                key={task.id} 
                className={`
                    relative p-4 rounded-xl border flex flex-col sm:flex-row sm:items-center gap-4 transition-all
                    ${isDue ? 'bg-white border-orange-200 shadow-sm' : 'bg-gray-50 border-gray-100 opacity-75'}
                `}
            >
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                    <h4 className="font-bold text-gray-800">{task.title}</h4>
                    {isDue && (
                        <span className="bg-red-100 text-red-600 text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-wider">
                            {daysOverdue > 0 ? `Overdue ${daysOverdue}d` : 'Due Today'}
                        </span>
                    )}
                </div>
                <div className="flex items-center gap-4 text-xs text-gray-500">
                    <span className="flex items-center gap-1">
                        <i className="fa-regular fa-clock"></i> {task.frequency}
                    </span>
                    {task.lastCompletedDate && (
                         <span className="flex items-center gap-1 text-green-600">
