import { Apartment, Area, Task, Frequency } from '../types';

const SHEET_ID = '1MWObX0LO9LB5xZMsfzMNKb73-V-wvlTwsh117PlDamY';
const CSV_URL = `https://docs.google.com/spreadsheets/d/${SHEET_ID}/export?format=csv`;

export interface SheetData {
  apartments: Apartment[];
  areas: Area[];
  tasks: Task[];
}

const generateId = (str: string) => str.toLowerCase().replace(/[^a-z0-9]/g, '-');

const parseCSVLine = (text: string) => {
    const result = [];
    let cell = '';
    let inQuotes = false;

    for (let i = 0; i < text.length; i++) {
        const char = text[i];
        if (char === '"') {
            if (inQuotes && text[i + 1] === '"') {
                cell += '"';
                i++;
            } else {
                inQuotes = !inQuotes;
            }
        } else if (char === ',' && !inQuotes) {
            result.push(cell.trim());
            cell = '';
        } else {
            cell += char;
        }
    }
    result.push(cell.trim());
    return result;
};

export const fetchSheetData = async (): Promise<SheetData | null> => {
  try {
    const response = await fetch(CSV_URL);
    if (!response.ok) throw new Error('Failed to fetch CSV');
    const text = await response.text();

    const rows = text.split('\n');
    const apartmentsMap = new Map<string, Apartment>();
    const areasMap = new Map<string, Area>();
    const tasks: Task[] = [];

    // Assuming Row 1 is header
    const dataRows = rows.slice(1);

    dataRows.forEach((row) => {
        if (!row.trim()) return;
        const cols = parseCSVLine(row);

        // Expected Columns: Apartment | Area | Task | Frequency
        // Fallbacks for missing columns
        const aptName = cols[0] || 'Main Apartment';
        const areaName = cols[1] || 'General';
        const taskTitle = cols[2] || 'Generic Task';
        const freqStr = cols[3] || 'Weekly';

        if (!taskTitle) return;

        // Create Apartment
        const aptId = generateId(aptName);
        if (!apartmentsMap.has(aptId)) {
            apartmentsMap.set(aptId, { id: aptId, name: aptName, address: 'Managed via Sheet' });
        }

        // Create Area
        const areaId = generateId(`${aptId}-${areaName}`);
        if (!areasMap.has(areaId)) {
             let icon = 'fa-box';
             const lower = areaName.toLowerCase();
             if (lower.includes('kitchen')) icon = 'fa-utensils';
             else if (lower.includes('bath') || lower.includes('toilet')) icon = 'fa-bath';
             else if (lower.includes('bed')) icon = 'fa-bed';
             else if (lower.includes('living') || lower.includes('lounge')) icon = 'fa-couch';
             else if (lower.includes('din')) icon = 'fa-chair';
             else if (lower.includes('ent')) icon = 'fa-door-open';
             else if (lower.includes('office')) icon = 'fa-briefcase';

             areasMap.set(areaId, { id: areaId, name: areaName, apartmentId: aptId, icon });
        }

        // Parse Frequency
        let frequency = Frequency.WEEKLY;
        const fLower = freqStr.toLowerCase();
        if (fLower.includes('daily')) frequency = Frequency.DAILY;
        else if (fLower.includes('bi-week') || fLower.includes('biweek')) frequency = Frequency.BIWEEKLY;
        else if (fLower.includes('month')) frequency = Frequency.MONTHLY;
        else if (fLower.includes('quarter')) frequency = Frequency.QUARTERLY;

        // Create Task
        // ID must be deterministic to match with LocalStorage
        const taskId = generateId(`${areaId}-${taskTitle}`);

        tasks.push({
            id: taskId,
            title: taskTitle,
            frequency,
            areaId: areaId,
            lastCompletedDate: null,
            nextDueDate: new Date().toISOString(), // Default, will be overwritten by state if exists
        });
    });

    return {
        apartments: Array.from(apartmentsMap.values()),
        areas: Array.from(areasMap.values()),
        tasks
    };

  } catch (e) {
    console.error("Error fetching sheet data", e);
    return null;
  }
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { AppState, Task, Apartment, Area, TaskStatus } from '../types';
import { loadState, saveState, calculateNextDueDate } from '../services/storageService';
import { fetchSheetData } from '../services/sheetService';

interface AppContextType {
  state: AppState;
  isLoading: boolean;
  completeTask: (taskId: string) => void;
  addTask: (task: Task) => void;
  setCurrentUser: (user: string) => void;
  getTasksByArea: (areaId: string) => Task[];
  getAreasByApartment: (aptId: string) => Area[];
  getApartmentProgress: (aptId: string) => { completed: number, total: number, percentage: number };
  getTotalProgress: () => { completed: number, total: number, percentage: number };
  refreshData: () => void;
  syncWithSheet: () => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>(loadState());
  const [isLoading, setIsLoading] = useState(false);

  // Initial Sync
  useEffect(() => {
    syncWithSheet();
  }, []);

  useEffect(() => {
    saveState(state);
  }, [state]);

  const syncWithSheet = async () => {
    setIsLoading(true);
    const sheetData = await fetchSheetData();

    if (sheetData) {
      setState(prevState => {
        // Merge strategy:
        // 1. Take structure (Apartments, Areas, Tasks definitions) from Sheet.
        // 2. Preserve status (lastCompletedDate, nextDueDate, assignedTo) from prevState (Local Storage) if ID matches.

        const mergedTasks = sheetData.tasks.map(sheetTask => {
          const existingTask = prevState.tasks.find(t => t.id === sheetTask.id);
          if (existingTask) {
            return {
              ...sheetTask,
              lastCompletedDate: existingTask.lastCompletedDate,
              nextDueDate: existingTask.nextDueDate,
              assignedTo: existingTask.assignedTo
            };
          }
          return sheetTask;
        });

        // If no tasks from sheet (e.g. empty sheet), keep existing state to avoid wiping data on error?
        // But here we successfully got data, so we should trust it.
        // However, if the sheet is empty, we might want to keep the "demo" data if it was untouched?
        // Let's assume user wants sheet data.

        return {
          ...prevState,
          apartments: sheetData.apartments,
          areas: sheetData.areas,
          tasks: mergedTasks
        };
      });
    }
    setIsLoading(false);
  };

  const refreshData = useCallback(() => {
    setState(loadState());
  }, []);

  const completeTask = (taskId: string) => {
    setState(prev => {
      const newTasks = prev.tasks.map(t => {
        if (t.id === taskId) {
          const now = new Date();
          const nextDue = calculateNextDueDate(t.frequency, now);
          return {
            ...t,
            lastCompletedDate: now.toISOString(),
            nextDueDate: nextDue.toISOString(),
            assignedTo: prev.currentUser
          };
        }
        return t;
      });
      return { ...prev, tasks: newTasks };
    });
  };

  const addTask = (task: Task) => {
    setState(prev => ({
      ...prev,
      tasks: [...prev.tasks, task]
    }));
  };

  const setCurrentUser = (user: string) => {
    setState(prev => ({ ...prev, currentUser: user }));
  };

  const getTasksByArea = (areaId: string) => {
    return state.tasks.filter(t => t.areaId === areaId);
  };

  const getAreasByApartment = (aptId: string) => {
    return state.areas.filter(a => a.apartmentId === aptId);
  };

  const getApartmentProgress = (aptId: string) => {
    const areaIds = state.areas.filter(a => a.apartmentId === aptId).map(a => a.id);
    const tasks = state.tasks.filter(t => areaIds.includes(t.areaId));

    if (tasks.length === 0) return { completed: 0, total: 0, percentage: 100 };

    const now = new Date();
    const pendingCount = tasks.filter(t => new Date(t.nextDueDate) <= now).length;
    const totalCount = tasks.length;
    const onTrackCount = totalCount - pendingCount;

    return {
      completed: onTrackCount,
      total: totalCount,
      percentage: totalCount === 0 ? 100 : Math.round((onTrackCount / totalCount) * 100)
    };
  };

  const getTotalProgress = () => {
     const tasks = state.tasks;
     if (tasks.length === 0) return { completed: 0, total: 0, percentage: 100 };

     const now = new Date();
     const pendingCount = tasks.filter(t => new Date(t.nextDueDate) <= now).length;
     const totalCount = tasks.length;
     const onTrackCount = totalCount - pendingCount;

     return {
      completed: onTrackCount,
      total: totalCount,
      percentage: totalCount === 0 ? 100 : Math.round((onTrackCount / totalCount) * 100)
    };
  };

  return (
    <AppContext.Provider value={{ 
      state, 
      isLoading,
      completeTask, 
      addTask, 
      setCurrentUser, 
      getTasksByArea, 
      getAreasByApartment,
      getApartmentProgress,
      getTotalProgress,
      refreshData,
      syncWithSheet
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) {
    throw new Error('useApp must be used within an AppProvider');
  }
  return context;
};

